<script setup>
import { ref, watch } from 'vue';
import { libraryRequest } from '../lib/library-client.js';
const props=defineProps({resource:{type:String,default:''},bookId:{type:String,default:''}});
const data=ref(null),books=ref([]),error=ref(''),pending=ref(false),offset=ref(0);
const cards=[['books','Bộ truyện','library'],['chapters','Chương','overview/chapters'],['current_audio','Audio hiện hành','overview/audio'],['audio_attention','Audio cần kiểm tra','overview/attention'],['merged_saved','Bản ghép đã lưu','overview/merged'],['jobs_attention','Công việc cần xử lý','jobs']];
const statuses={audio_ready:'Audio hiện hành',needs_refresh:'Cần kiểm tra lại',source_ready:'Đã có nội dung',completed:'Hoàn thành',failed:'Có lỗi',running:'Đang chạy',queued:'Đang chờ',stopped:'Đã dừng',interrupted:'Bị gián đoạn'};
function link(path,attention=false){const q=new URLSearchParams();if(props.bookId)q.set('book',props.bookId);if(attention)q.set('status','attention');if(path==='library'&&props.bookId)return '#library/'+props.bookId;return '#'+path+(q.size?'?'+q:'');}
let generation=0;
async function load(){const run=++generation;pending.value=true;error.value='';try{const result=await libraryRequest('?'+new URLSearchParams({book_id:props.bookId||'',resource:props.resource,offset:offset.value,limit:20}).toString().replace('book_id=&',''),undefined,'GET','overview');if(run===generation)data.value=result;}catch(e){if(run===generation)error.value=e.message;}finally{if(run===generation)pending.value=false;}}
function scope(event){location.hash='#overview'+(props.resource?'/'+props.resource:'')+(event.target.value?'?book='+event.target.value:'');}
watch(()=>[props.resource,props.bookId],()=>{offset.value=0;data.value=null;load();},{immediate:true});
libraryRequest('?limit=100').then(x=>books.value=x.items).catch(e=>error.value=e.message);
</script>
<template>
<section class="mt-6 space-y-5" aria-label="Tổng quan thực tế">
 <div class="flex flex-wrap items-end justify-between gap-3"><label class="grid gap-2 text-xs" for="overview-scope">Phạm vi<select id="overview-scope" :value="bookId" class="max-w-full rounded border border-line bg-surface p-2" @change="scope"><option value="">Toàn thư viện</option><option v-for="book in books" :key="book.id" :value="book.id">{{book.name}}</option></select></label><button class="text-xs text-brand underline" :disabled="pending" @click="load">Cập nhật số liệu</button></div>
 <p v-if="error" role="alert" class="rounded border border-line p-4 text-sm">{{error}}</p><p v-if="pending" role="status" class="text-xs text-muted">Đang cập nhật…</p>
 <template v-if="data"><div class="grid grid-cols-2 gap-3 lg:grid-cols-3"><a v-for="card in cards" :key="card[0]" :href="link(card[2],card[0]==='jobs_attention')" :data-count="card[0]" class="rounded-xl border border-line bg-surface p-5 hover:border-brand"><strong class="block text-2xl">{{data.counts[card[0]]}}</strong><span class="mt-2 block text-xs text-muted">{{card[1]}}</span></a></div><p class="text-xs leading-5 text-muted">{{data.notice}}</p>
 <article v-if="resource" class="rounded-xl border border-line bg-surface p-5"><h2 class="text-base font-semibold">{{{chapters:'Các chương',audio:'Audio hiện hành',attention:'Audio cần kiểm tra',merged:'Bản ghép đã lưu'}[resource]||'Kết quả'}}</h2><p v-if="!data.items.length" class="mt-4 text-sm text-muted">Chưa có kết quả trong phạm vi này.</p><ul class="mt-3 divide-y divide-line"><li v-for="row in data.items" :key="row.id" class="py-3 text-sm"><a class="text-brand underline" :href="row.job_id?'#jobs/'+row.job_id:'#library/'+row.book_id+'/'+row.id">{{row.book_name}} · {{row.job_id?'Bản ghép '+row.id.slice(0,8):'Chương '+row.number+' · '+row.title}}</a><p class="mt-1 text-xs text-muted">{{statuses[row.status]|| (row.duration?.toFixed(2)+' giây')}}</p></li></ul><div class="mt-4 flex items-center gap-4 text-xs"><button :disabled="pending||offset===0" class="text-brand disabled:opacity-40" @click="offset-=20;load()">← Trước</button><span>{{data.total}} kết quả · {{Math.floor(offset/20)+1}}</span><button :disabled="pending||offset+20>=data.total" class="text-brand disabled:opacity-40" @click="offset+=20;load()">Sau →</button></div></article>
 <article class="rounded-xl border border-line bg-surface p-5"><h2 class="text-base font-semibold">Công việc gần đây</h2><p v-if="!data.recent_jobs.length" class="mt-4 text-sm text-muted">Chưa có công việc.</p><ul class="mt-3 divide-y divide-line"><li v-for="job in data.recent_jobs" :key="job.id" class="flex flex-wrap justify-between gap-2 py-3 text-xs"><a class="text-brand underline" :href="link('jobs/'+job.id)">{{job.kind}} · {{job.id.slice(0,8)}}</a><span>{{statuses[job.status]||job.status}}</span></li></ul><a :href="link('jobs')" class="mt-3 inline-block text-xs text-brand underline">Mở lịch sử công việc →</a></article></template>
</section>
</template>
